    let plain = Series::of(means);
    let trimmed = Trimmed::of(means, trim);
    let claims: Vec<String> = plain
        .iter()
        .flat_map(|s| [claim(s.ci95()), claim(s.lsc())])
        .chain(
            trimmed
                .iter()

